user_message:
Compare the typed predicate candidates against the existing registry.
Candidate predicates:
[
  {
    "name": "USES_OBSERVATION_AS_INPUT",
    "definition": "The action takes an identifiable value or data payload supplied by the specified prior observation as an operational input (for example a returned file path used as a read target, or a resolved download location passed into a subsequent command).",
    "parameters": [
      {
        "name": "action",
        "type": "action",
        "description": "The action that receives the input value or data payload."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The earlier recorded tool result that supplies the value or payload consumed by the action."
      }
    ],
    "assertion_conditions": [
      "The observation and the receiving action are both present in the detailed trajectory, with the observation occurring before the action.",
      "An argument, path, URL, column name or data payload of the action can be traced to content of that observation."
    ],
    "exclusion_conditions": [
      "Information that only motivated which action to take, without appearing as an argument or payload of it, does not satisfy this predicate.",
      "Shared topic or temporal adjacency between an observation and an action does not satisfy this predicate.",
      "A result produced by the action itself (its returning observation) cannot be an input to that same action."
    ]
  },
  {
    "name": "USES_REASONING_AS_INPUT",
    "definition": "The action takes an identifiable value, procedure or content specification supplied by the specified prior reasoning node as an operational input (for example a written script whose computation steps and field selection implement the procedure stated in the reasoning text).",
    "parameters": [
      {
        "name": "action",
        "type": "action",
        "description": "The action whose arguments or payload embody the supplied specification."
      },
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The earlier recorded agent text stating the procedure, interpretation or content that the action operationalizes."
      }
    ],
    "assertion_conditions": [
      "The reasoning node precedes the action and states a procedure, interpretation or content specification.",
      "The action's arguments or payload can be traced to that stated specification rather than to a generic restatement of the user query."
    ],
    "exclusion_conditions": [
      "A reasoning node that merely restates the task statement, without an operational specification realizing it in the action, does not satisfy this predicate.",
      "A plain narrative mention of the action without the action's content implementing it does not satisfy this predicate."
    ]
  },
  {
    "name": "GUIDES_ACTION_CHOICE",
    "definition": "The specified observation supplies the explicit basis on which the subsequent action was selected among alternatives, as evidenced by the surrounding recorded text tying that result to the choice.",
    "parameters": [
      {
        "name": "observation",
        "type": "observation",
        "description": "The recorded tool result whose content is the stated basis for the decision."
      },
      {
        "name": "action",
        "type": "action",
        "description": "The action chosen after and on account of that result."
      }
    ],
    "assertion_conditions": [
      "The observation occurs before the chosen action.",
      "Recorded agent text identifies the observation's content (for example an error message or a returned listing) as the reason for choosing this action over other available options."
    ],
    "exclusion_conditions": [
      "An observation used only as a data argument to an action, without motivating the choice, does not satisfy this predicate.",
      "Sequential ordering alone, with no recorded statement of the decision basis, does not satisfy this predicate."
    ]
  },
  {
    "name": "DIAGNOSES_FAILURE",
    "definition": "The reasoning node identifies or hypothesizes the cause of an unsuccessful result reported by the specified observation, explaining why the preceding operation did not succeed.",
    "parameters": [
      {
        "name": "failure",
        "type": "observation",
        "description": "The recorded result whose content indicates that the operation did not produce the intended outcome."
      },
      {
        "name": "diagnosis",
        "type": "reasoning",
        "description": "The recorded agent text explaining or hypothesizing the cause of that unsuccessful result."
      }
    ],
    "assertion_conditions": [
      "The observation reports an error, invalid credential message, mismatch, or otherwise unintended outcome.",
      "The reasoning node follows that observation and attributes a cause or explanation to it, such as an authentication or access-path problem."
    ],
    "exclusion_conditions": [
      "Reasoning that only restates the failure without offering a cause does not satisfy this predicate.",
      "A plan for how to proceed, stated without any causal explanation of the failure, does not by itself satisfy this predicate."
    ]
  },
  {
    "name": "ATTEMPTS_REPAIR",
    "definition": "The action is performed with the intent of overcoming a specific unsuccessful result reported by the specified observation, for example by retrying the retrieval through a different channel instead of the channel that failed.",
    "parameters": [
      {
        "name": "repair",
        "type": "action",
        "description": "The action undertaken to work around or fix the observed failure."
      },
      {
        "name": "failure",
        "type": "observation",
        "description": "The earlier recorded result reporting the failed operation that the action targets."
      }
    ],
    "assertion_conditions": [
      "The failure observation precedes the repair action.",
      "Recorded text or the action's arguments tie the action to that specific failure, such as switching to an alternative endpoint, download helper, or corrected identifier."
    ],
    "exclusion_conditions": [
      "An unrelated next step that happens to follow a failure does not satisfy this predicate.",
      "The repair action alone does not establish that the problem was fixed; success requires a separate later confirming result."
    ]
  },
  {
    "name": "PROVISIONS_MISSING_CAPABILITY",
    "definition": "The action installs or otherwise establishes a capability that the specified earlier observation showed to be absent from the environment, when the absence is not itself an error but a reported deficiency.",
    "parameters": [
      {
        "name": "action",
        "type": "action",
        "description": "The action that adds the absent capability to the environment."
      },
      {
        "name": "deficiency",
        "type": "observation",
        "description": "The earlier recorded result listing or reporting the absent capability, such as an installed-package listing that lacks required libraries."
      }
    ],
    "assertion_conditions": [
      "The deficiency observation precedes the action and reports the capability as unavailable or not installed.",
      "The action installs or provisions exactly the capability whose absence was reported."
    ],
    "exclusion_conditions": [
      "Installing packages that were never reported missing does not satisfy this predicate.",
      "An observation reporting an execution error rather than an absent capability belongs to a failure-repair mechanism instead."
    ]
  },
  {
    "name": "DERIVES_CONCLUSION",
    "definition": "The reasoning node states a conclusion about the subject matter that is drawn from the content of one or more prior observations, such as inferring a dataset's subset structure and field names from retrieved documentation.",
    "parameters": [
      {
        "name": "inputs",
        "type": "observation[]",
        "description": "The prior recorded results whose content is the basis for the conclusion."
      },
      {
        "name": "conclusion",
        "type": "reasoning",
        "description": "The recorded agent text asserting the conclusion drawn from those results."
      }
    ],
    "assertion_conditions": [
      "The referenced observations precede the conclusion node.",
      "The conclusion's content corresponds to information present in those observations and goes beyond restating the user query, for example by naming the available subset and its columns."
    ],
    "exclusion_conditions": [
      "A conclusion with no traceable basis in the listed observations does not satisfy this predicate.",
      "An observation is not automatically a verified fact; a conclusion that treats a retrieved document as authoritative requires that the derivation be visible in the reasoning text."
    ]
  },
  {
    "name": "IS_PLAN",
    "definition": "The reasoning node contains an explicit, ordered or itemized plan of steps that the agent intends to execute to accomplish the task.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The recorded agent text containing the enumerated steps to be carried out."
      }
    ],
    "assertion_conditions": [
      "The text enumerates multiple intended steps or a sequence of operations to perform.",
      "The steps are presented as future actions to take rather than as a narrative of completed work."
    ],
    "exclusion_conditions": [
      "A single intended next action or a restatement of the task requirements does not satisfy this predicate.",
      "A summary of already-performed actions does not satisfy this predicate."
    ]
  }
]

